import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';
import session from 'express-session';

interface FirmwareDevice {
  id: string;
  name: string;
  version: string;
  lastUpdate: number;
}

interface AuditEntry {
  timestamp: number;
  action: string;
  userId: string;
  deviceId: string;
  origin: string;
  verified: boolean;
}

const app = express();
const auditLog: AuditEntry[] = [];
const devices: Map<string, FirmwareDevice> = new Map();
const SESSION_SECRET = crypto.randomBytes(32).toString('hex');

app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(session({
  secret: SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, secure: true, sameSite: 'strict' }
}));

function generateToken(sessionId: string): string {
  const hmac = crypto.createHmac('sha256', SESSION_SECRET);
  hmac.update(sessionId);
  return hmac.digest('hex');
}

function validateTokenBinding(token: string, sessionId: string): boolean {
  const expected = generateToken(sessionId);
  const tokenBuf = Buffer.from(token);
  const expectedBuf = Buffer.from(expected);
  // Length check before timingSafeEqual to avoid RangeError on
  // attacker-supplied tokens of differing length.
  if (tokenBuf.length !== expectedBuf.length) {
    return false;
  }
  return crypto.timingSafeEqual(tokenBuf, expectedBuf);
}

function logAudit(action: string, userId: string, deviceId: string, origin: string, verified: boolean) {
  auditLog.push({ timestamp: Date.now(), action, userId, deviceId, origin, verified });
}

function requireAuth(req: Request, res: Response, next: NextFunction) {
  if (!(req.session as any)?.userId) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  next();
}

interface CSRFProtectionOptions {
  headerName: string;
  paramName: string;
  enforceOrigin: boolean;
}

function csrfProtection(options: CSRFProtectionOptions) {
  return (req: Request, res: Response, next: NextFunction) => {
    if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') {
      return next();
    }

    const sessionId = (req.session as any)?.id;
    if (!sessionId) {
      return res.status(403).json({ error: 'No session' });
    }

    // Check origin header if enforcement is enabled
    if (options.enforceOrigin) {
      const origin = req.headers['origin'] || req.headers['referer'];
      if (origin && !isAllowedOrigin(origin as string)) {
        logAudit('CSRF_BLOCKED', (req.session as any).userId || 'unknown', '', origin as string, false);
        return res.status(403).json({ error: 'Origin not allowed' });
      }
    }

    // Token validation from header or body parameter
    const token = req.headers[options.headerName] as string || req.body?.[options.paramName];

    if (!token) {
      logAudit('CSRF_MISSING_TOKEN', (req.session as any).userId || 'unknown', '', req.headers['origin'] as string || '', false);
      return res.status(403).json({ error: 'CSRF token required' });
    }

    try {
      if (!validateTokenBinding(token, sessionId)) {
        logAudit('CSRF_INVALID_TOKEN', (req.session as any).userId || 'unknown', '', req.headers['origin'] as string || '', false);
        return res.status(403).json({ error: 'Invalid CSRF token' });
      }
    } catch (e) {
      return res.status(403).json({ error: 'Token validation failed' });
    }

    next();
  };
}

function isAllowedOrigin(origin: string): boolean {
  const allowed = ['https://iot-admin.internal.corp', 'https://firmware.internal.corp'];
  try {
    const url = new URL(origin);
    return allowed.some(a => url.origin === new URL(a).origin);
  } catch {
    return false;
  }
}

const csrf = csrfProtection({
  headerName: 'x-csrf-token',
  paramName: '_csrf',
  enforceOrigin: true
});

// Firmware update endpoint - state-changing, needs CSRF protection
app.post('/api/devices/:id/firmware', requireAuth, csrf, (req: Request, res: Response) => {
  const device = devices.get(req.params.id);
  if (!device) return res.status(404).json({ error: 'Device not found' });

  const { version, firmwareUrl } = req.body;
  device.version = version;
  device.lastUpdate = Date.now();

  logAudit('FIRMWARE_UPDATE', (req.session as any).userId, device.id, req.headers['origin'] as string || 'direct', true);
  res.json({ success: true, device });
});

// Device reboot endpoint
app.post('/api/devices/:id/reboot', requireAuth, csrf, (req: Request, res: Response) => {
  const device = devices.get(req.params.id);
  if (!device) return res.status(404).json({ error: 'Device not found' });

  logAudit('DEVICE_REBOOT', (req.session as any).userId, device.id, req.headers['origin'] as string || 'direct', true);
  res.json({ success: true, message: `Rebooting ${device.name}` });
});

// Bulk device configuration - protected by CSRF token validation
app.post('/api/devices/bulk-configure', requireAuth, csrf, (req: Request, res: Response) => {
  const contentType = req.headers['content-type'] || '';

  // JSON-RPC style endpoint: only accept application/json-rpc
  if (!contentType.includes('application/json-rpc')) {
    return res.status(415).json({ error: 'Unsupported media type. Use application/json-rpc' });
  }

  const { method, params } = req.body;

  if (method === 'configure') {
    const results: any[] = [];
    for (const deviceConfig of params.devices || []) {
      const device = devices.get(deviceConfig.id);
      if (device) {
        device.name = deviceConfig.name || device.name;
        results.push({ id: device.id, status: 'configured' });
        logAudit('BULK_CONFIGURE', (req.session as any).userId, device.id, req.headers['origin'] as string || 'direct', true);
      }
    }
    return res.json({ result: results });
  }

  if (method === 'factory-reset') {
    for (const deviceId of params.deviceIds || []) {
      const device = devices.get(deviceId);
      if (device) {
        device.version = '1.0.0';
        logAudit('FACTORY_RESET', (req.session as any).userId, device.id, req.headers['origin'] as string || 'direct', true);
      }
    }
    return res.json({ result: 'reset initiated' });
  }

  res.status(400).json({ error: 'Unknown method' });
});

// Get CSRF token
app.get('/api/csrf-token', requireAuth, (req: Request, res: Response) => {
  const token = generateToken((req.session as any).id);
  res.json({ token });
});

// Audit log viewer
app.get('/api/audit', requireAuth, (req: Request, res: Response) => {
  res.json({ entries: auditLog.slice(-100) });
});

app.listen(3000, '127.0.0.1');
export default app;
